Json::Value Users::toJson() const
{
    Json::Value ret;

    if(getId())
    {

        ret["id"]=getValueOfId();

    }
    else
    {
        ret["id"]=Json::Value();
    }

    if(getUsername())
    {

        ret["username"]=getValueOfUsername();

    }
    else
    {
        ret["username"]=Json::Value();
    }

    if(getEmail())
    {

        ret["email"]=getValueOfEmail();

    }
    else
    {
        ret["email"]=Json::Value();
    }

    if(getPasswordHash())
    {

        ret["password_hash"]=getValueOfPasswordHash();

    }
    else
    {
        ret["password_hash"]=Json::Value();
    }

    if(getCreatedAt())
    {

        ret["created_at"]=getCreatedAt()->toDbStringLocal();

    }
    else
    {
        ret["created_at"]=Json::Value();
    }

    if(getUpdatedAt())
    {

        ret["updated_at"]=getUpdatedAt()->toDbStringLocal();

    }
    else
    {
        ret["updated_at"]=Json::Value();
    }

    if(getIsActive())
    {

        ret["is_active"]=getValueOfIsActive();

    }
    else
    {
        ret["is_active"]=Json::Value();
    }

    if(getRole())
    {

        ret["role"]=getValueOfRole();

    }
    else
    {
        ret["role"]=Json::Value();
    }

    return ret;
}

